CREATE TABLE IF NOT EXISTS members (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, mobile VARCHAR(15), address VARCHAR(255), joining_date VARCHAR(50), role VARCHAR(50), status VARCHAR(20) DEFAULT 'ACTIVE');`nCREATE TABLE IF NOT EXISTS collections (id INT AUTO_INCREMENT PRIMARY KEY, member_id INT, receipt_no VARCHAR(50), amount DECIMAL(10,2), collection_date VARCHAR(50), payment_mode VARCHAR(50), purpose VARCHAR(100), remarks VARCHAR(255), FOREIGN KEY (member_id) REFERENCES members(id));`nCREATE TABLE IF NOT EXISTS expenses (id INT AUTO_INCREMENT PRIMARY KEY, expense_date VARCHAR(50), category VARCHAR(100), description VARCHAR(255), amount DECIMAL(10,2), paid_to VARCHAR(100), payment_mode VARCHAR(50), remarks VARCHAR(255));
